using RegistrationService.Data;using RegistrationService.Endpoints;using RegistrationService.Messaging;using Microsoft.EntityFrameworkCore;using Microsoft.OpenApi.Models;var builder=WebApplication.CreateBuilder(args);builder.Services.AddEndpointsApiExplorer();builder.Services.AddSwaggerGen(o=>{o.SwaggerDoc("v1",new OpenApiInfo{Title="WAEC Registration Service API",Version="v1"});o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header});o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});builder.Services.AddDbContext<RegistrationDbContext>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("Registrations")??throw new InvalidOperationException("ConnectionStrings:Registrations is required.")));builder.Services.AddSingleton<RegistrationEventPublisher>();var app=builder.Build();app.UseSwagger();app.UseSwaggerUI(o=>{o.SwaggerEndpoint("/swagger/v1/swagger.json","WAEC Registration Service API V1");o.RoutePrefix="swagger";});await DatabaseInitializer.InitializeAsync(app.Services);app.MapRegistrationEndpoints();app.Run();